        field_combo.mcycleh.MCYCLEH.next = next_c;
        field_combo.mcycleh.MCYCLEH.load_next = load_next_c;
    end
    always_ff @(posedge clk) begin
        if(rst) begin
            field_storage.mcycleh.MCYCLEH.value <= 32'h0;
        end else begin
            if(field_combo.mcycleh.MCYCLEH.load_next) begin
                field_storage.mcycleh.MCYCLEH.value <= field_combo.mcycleh.MCYCLEH.next;
            end
        end
    end
    assign hwif_out.mcycleh.MCYCLEH.value = field_storage.mcycleh.MCYCLEH.value;
    // Field: csr_regfile.minstreth.MINSTRETH
    always_comb begin
        automatic logic [31:0] next_c;
        automatic logic load_next_c;
        next_c = field_storage.minstreth.MINSTRETH.value;
        load_next_c = '0;
        if(decoded_reg_strb.minstreth && decoded_req_is_wr) begin // SW write
            next_c = (field_storage.minstreth.MINSTRETH.value & ~decoded_wr_biten[31:0]) | (decoded_wr_data[31:0] & decoded_wr_biten[31:0]);
            load_next_c = '1;
        end else if(hwif_in.minstreth.MINSTRETH.we) begin // HW Write - we
            next_c = hwif_in.minstreth.MINSTRETH.next;
            load_next_c = '1;
        end
        field_combo.minstreth.MINSTRETH.next = next_c;
        field_combo.minstreth.MINSTRETH.load_next = load_next_c;
    end
    always_ff @(posedge clk) begin
        if(rst) begin
            field_storage.minstreth.MINSTRETH.value <= 32'h0;
        end else begin
            if(field_combo.minstreth.MINSTRETH.load_next) begin
                field_storage.minstreth.MINSTRETH.value <= field_combo.minstreth.MINSTRETH.next;
            end
        end
    end
    assign hwif_out.minstreth.MINSTRETH.value = field_storage.minstreth.MINSTRETH.value;

    //--------------------------------------------------------------------------
    // Write response
    //--------------------------------------------------------------------------
    assign cpuif_wr_ack = decoded_req & decoded_req_is_wr;
    // Writes are always granted with no error response
    assign cpuif_wr_err = '0;

    //--------------------------------------------------------------------------
    // Readback
    //--------------------------------------------------------------------------

    logic [6:0] rd_mux_addr;
    assign rd_mux_addr = decoded_addr;

    logic readback_err;
    logic readback_done;
    logic [31:0] readback_data;
    always_comb begin
        automatic logic [31:0] readback_data_var;
        readback_data_var = '0;
        if(rd_mux_addr == 7'h0) begin
            readback_data_var[3] = field_storage.mstatus.MIE.value;
            readback_data_var[7] = field_storage.mstatus.MPIE.value;
            readback_data_var[12:11] = 2'h3;
        end
        if(rd_mux_addr == 7'h4) begin
            readback_data_var[31:0] = 32'h40000100;
        end
        if(rd_mux_addr == 7'h8) begin
            readback_data_var[3] = field_storage.mie.MSIE.value;
            readback_data_var[7] = field_storage.mie.MTIE.value;
            readback_data_var[11] = field_storage.mie.MEIE.value;
        end
        if(rd_mux_addr == 7'hc) begin
            readback_data_var[31:0] = field_storage.mtvec.MTVEC.value;
        end
        if(rd_mux_addr == 7'h10) begin
            readback_data_var[31:0] = field_storage.mscratch.MSCRATCH.value;
        end
        if(rd_mux_addr == 7'h14) begin
            readback_data_var[1:0] = 2'h0;
            readback_data_var[31:2] = field_storage.mepc.MEPC_HI.value;
        end
        if(rd_mux_addr == 7'h18) begin
            readback_data_var[31:0] = field_storage.mcause.MCAUSE.value;
        end
        if(rd_mux_addr == 7'h1c) begin
            readback_data_var[31:0] = field_storage.mtval.MTVAL.value;
        end
        if(rd_mux_addr == 7'h20) begin
            readback_data_var[31:0] = 32'h0;
        end
        if(rd_mux_addr == 7'h24) begin
            readback_data_var[31:0] = field_storage.mcycle.MCYCLE.value;
        end
        if(rd_mux_addr == 7'h28) begin
            readback_data_var[31:0] = field_storage.minstret.MINSTRET.value;
        end
        if(rd_mux_addr == 7'h2c) begin
            readback_data_var[31:0] = field_storage.mcycleh.MCYCLEH.value;
        end
        if(rd_mux_addr == 7'h30) begin
            readback_data_var[31:0] = field_storage.minstreth.MINSTRETH.value;
        end
        if(rd_mux_addr == 7'h34) begin
            readback_data_var[31:0] = 32'h0;
        end
        if(rd_mux_addr == 7'h38) begin
            readback_data_var[31:0] = 32'h0;
        end
        if(rd_mux_addr == 7'h3c) begin
            readback_data_var[31:0] = 32'h0;
        end
        if(rd_mux_addr == 7'h40) begin
            readback_data_var[31:0] = 32'h0;
        end
        readback_data = readback_data_var;
        readback_done = decoded_req & ~decoded_req_is_wr;
        readback_err = '0;
    end

    assign cpuif_rd_ack = readback_done;
    assign cpuif_rd_data = readback_data;
    assign cpuif_rd_err = readback_err;
endmodule
